DELETE FROM rewards_ledger;
DELETE FROM rewards_balances;
DELETE FROM disputes;
DELETE FROM payments;
DELETE FROM unbilled_transactions;
DELETE FROM statement_lines;
DELETE FROM statements;
DELETE FROM cards;
DELETE FROM _counters;
UPDATE unbilled_transactions
SET merchant_name = CASE CAST(substr(tx_id,-3) AS INTEGER) % 10
      WHEN 0 THEN 'Greenway Pharmacy' WHEN 1 THEN 'Metro Transit' WHEN 2 THEN 'Northside Grocery Co-op'
      WHEN 3 THEN 'Memorial Travel Hotel' WHEN 4 THEN 'City Utilities' WHEN 5 THEN 'Northstar Custody Document Fee'
      WHEN 6 THEN 'Family Medical Clinic' WHEN 7 THEN 'Home Office Supply' WHEN 8 THEN 'Airport Shuttle' ELSE 'Neighborhood Cafe' END,
    category = CASE CAST(substr(tx_id,-3) AS INTEGER) % 5 WHEN 0 THEN 'medical' WHEN 1 THEN 'transport' WHEN 2 THEN 'household' WHEN 3 THEN 'estate_support' ELSE 'daily' END;

UPDATE rewards_ledger
SET note = CASE kind
      WHEN 'earn' THEN 'Rewards earned on ordinary card activity; posted ' || substr(posted_at,1,10) || '; not cash available for bills.'
      WHEN 'redeem' THEN 'Rewards redemption posted ' || substr(posted_at,1,10) || '; reconcile statement credit separately.'
      ELSE 'Issuer rewards adjustment posted ' || substr(posted_at,1,10) || '; verify balance and reason.'
    END;

-- Source provenance belongs in the research archive, not in merchant fields.
UPDATE statement_lines SET merchant_name='Northstar Custody document-copy fee', category='estate_admin' WHERE line_id='sl_iirtg_0021';
